mapper.sql:
WHERE co.is_active = #{filter.status}
AND cod.crm_pipeline_setting_id IN (
    SELECT crm_pipeline_setting_id FROM crm_pipeline_setting_egroups
    WHERE egroup_id IN (
        SELECT egroup_id FROM employee_egroups
        WHERE employee_id IN (SELECT id FROM employees WHERE user_id = #{userId})
    )
)

    AND cod.crm_pipeline_setting_id = #{filter.pipelineId}


    AND co.responsibility_id = #{filter.createdBy}



    AND cod.crm_opportunity_stag_id = #{filter.stageId}




    AND co.customer_id = #{filter.organizationId}


    AND DATE(co.expected_date) >= #{filter.dateFrom}


    AND DATE(co.expected_date) <= #{filter.dateTo}


    AND (
        co.name LIKE CONCAT("%", #{filter.searchText}, "%")
        OR co.code LIKE CONCAT("%", #{filter.searchText}, "%")
        OR customers.name LIKE CONCAT("%", #{filter.searchText}, "%")
        OR cos.name LIKE CONCAT("%", #{filter.searchText}, "%")
    )

mapper.select:
SELECT



GROUP BY co.id
ORDER BY

    ${filter.orderBy}
    cod.crm_pipeline_setting_id DESC, cod.crm_opportunity_stag_id DESC, co.id DESC


    LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT


WHERE co.is_active IN (1, 2)
AND co.id = #{id}

