UPDATE crm_opportunity_details
SET is_active = 2
WHERE crm_opportunity_id = #{opportunityId}
AND crm_pipeline_setting_id = #{pipelineId}

    AND crm_opportunity_stag_id = #{stageId}

AND is_active = 1

UPDATE crm_opportunity_details
SET description = #{description}
WHERE id = #{detailId}

UPDATE crm_opportunity_details
SET description = #{description},
    is_convert = 1,
    converted = NOW(),
    converted_by = #{userId}
WHERE crm_opportunity_id = #{opportunityId}

UPDATE crm_opportunity_details
SET is_active = 0
WHERE id = #{detailId}

UPDATE crm_opportunity_details
SET is_convert = 0
WHERE id = #{detailId}

UPDATE crm_opportunities
SET modified = NOW(),
    modified_by = #{userId}
WHERE id = #{opportunityId}
AND is_active = 1
